use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

/// The allowlist the `HTTPClient<[...]>` handle is scoped to. The host enforces
/// it at the crossing; this pre-check only turns an out-of-scope URL into a
/// recorded failure instead of a trap that would abort the whole batch.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

struct Node;

/// Extract the lowercased host of an http(s) URL. Returns `None` for anything
/// that is not a plain `scheme://host[:port]/...` form, including URLs carrying
/// userinfo (`user@host`) or IPv6 literals, so ambiguous URLs fail closed.
fn host_of(url: &str) -> Option<String> {
    let rest = url
        .strip_prefix("https://")
        .or_else(|| url.strip_prefix("http://"))?;
    let authority = rest.split(['/', '?', '#']).next()?;
    if authority.contains('@') || authority.contains('[') {
        return None;
    }
    let host = authority.split(':').next()?;
    if host.is_empty() {
        return None;
    }
    Some(host.to_ascii_lowercase())
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();

        for url in subscriptions.urls {
            let host = match host_of(&url) {
                Some(h) => h,
                None => {
                    failures.push(FetchFailure {
                        url,
                        error: "unparseable URL".to_string(),
                    });
                    continue;
                }
            };

            if !ALLOWED_HOSTS.contains(&host.as_str()) {
                failures.push(FetchFailure {
                    url,
                    error: "host not in allowlist".to_string(),
                });
                continue;
            }

            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
